insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'en-italian-food-trivia',
  'Italian Food Trivia: Pasta, Pizza and the Classics',
  'Eight questions on the dishes and protected products of Italy: pizza Margherita, pasta shapes, risotto, tiramisu and the DOP label.',
  'trivia',
  'medium',
  'en',
  (select id from public.categories where slug = 'food-drink'),
  '[{"id":"q1","question":"According to tradition, pizza Margherita''s toppings echo the Italian flag. Which three are they?","options":[{"id":"a","text":"Tomato, mozzarella and basil","is_correct":true},{"id":"b","text":"Pepperoni, mushrooms and onion","is_correct":false},{"id":"c","text":"Ham, pineapple and olives","is_correct":false},{"id":"d","text":"Anchovies, capers and oregano","is_correct":false}],"explanation":"Tomato red, mozzarella white and basil green mirror the flag; tradition links the pizza to Queen Margherita of Savoy in 1889."},{"id":"q2","question":"Which pasta shape takes its name from the Italian for ''little ears''?","options":[{"id":"a","text":"Farfalle","is_correct":false},{"id":"b","text":"Orecchiette","is_correct":true},{"id":"c","text":"Fusilli","is_correct":false},{"id":"d","text":"Rigatoni","is_correct":false}],"explanation":"Orecchiette means ''little ears'' in Italian; it is a signature pasta of the Puglia region."},{"id":"q3","question":"Risotto alla milanese, coloured with saffron, is a classic dish of which city?","options":[{"id":"a","text":"Venice","is_correct":false},{"id":"b","text":"Naples","is_correct":false},{"id":"c","text":"Milan","is_correct":true},{"id":"d","text":"Florence","is_correct":false}],"explanation":"Risotto alla milanese is named after Milan, in Lombardy; saffron gives the dish its golden colour."},{"id":"q4","question":"Which creamy cheese is essential in a classic tiramisu?","options":[{"id":"a","text":"Mascarpone","is_correct":true},{"id":"b","text":"Ricotta","is_correct":false},{"id":"c","text":"Gorgonzola","is_correct":false},{"id":"d","text":"Provolone","is_correct":false}],"explanation":"Tiramisu layers savoiardi biscuits soaked in coffee with a mascarpone cream."},{"id":"q5","question":"Authentic carbonara is made with which cured meat?","options":[{"id":"a","text":"Smoked bacon","is_correct":false},{"id":"b","text":"Guanciale","is_correct":true},{"id":"c","text":"Salami","is_correct":false},{"id":"d","text":"Cooked ham","is_correct":false}],"explanation":"Guanciale, cured pork jowl, is the traditional meat of carbonara in Rome, with egg and pecorino cheese."},{"id":"q6","question":"Classic pesto alla genovese is made by crushing basil with which nuts?","options":[{"id":"a","text":"Walnuts","is_correct":false},{"id":"b","text":"Almonds","is_correct":false},{"id":"c","text":"Pine nuts","is_correct":true},{"id":"d","text":"Hazelnuts","is_correct":false}],"explanation":"Pesto alla genovese combines basil, pine nuts, garlic, olive oil and aged cheese."},{"id":"q7","question":"The protected production zone of Parmigiano-Reggiano cheese is centred on which region?","options":[{"id":"a","text":"Emilia-Romagna","is_correct":true},{"id":"b","text":"Sicily","is_correct":false},{"id":"c","text":"Piedmont","is_correct":false},{"id":"d","text":"Sardinia","is_correct":false}],"explanation":"Its protected zone covers Parma, Reggio Emilia, Modena and parts of Bologna and Mantua provinces."},{"id":"q8","question":"What does the ''DOP'' label on an Italian food certify?","options":[{"id":"a","text":"That it is organic","is_correct":false},{"id":"b","text":"That it is made in a defined area using recognised methods","is_correct":true},{"id":"c","text":"That it contains no additives","is_correct":false},{"id":"d","text":"That it is exported only within the EU","is_correct":false}],"explanation":"DOP stands for Denominazione di Origine Protetta, the protected designation of origin."}]'::jsonb,
  null,
  array['food', 'trivia', 'italy', 'italian cuisine']::text[],
  3,
  'published',
  false,
  false,
  now()
)
on conflict (slug) do nothing;

insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'es-trivia-comida-italiana',
  'Trivia de comida italiana: pasta, pizza y clásicos',
  'Ocho preguntas sobre platos y productos protegidos de Italia: pizza margarita, formas de pasta, risotto, tiramisú y el sello DOP.',
  'trivia',
  'medium',
  'es',
  (select id from public.categories where slug = 'food-drink'),
  '[{"id":"q1","question":"Según la tradición, los ingredientes de la pizza margarita evocan la bandera italiana. ¿Cuáles son?","options":[{"id":"a","text":"Tomate, mozzarella y albahaca","is_correct":true},{"id":"b","text":"Pepperoni, champiñones y cebolla","is_correct":false},{"id":"c","text":"Jamón, piña y aceitunas","is_correct":false},{"id":"d","text":"Anchoas, alcaparras y orégano","is_correct":false}],"explanation":"El rojo del tomate, el blanco de la mozzarella y el verde de la albahaca imitan la bandera; la tradición la vincula a la reina Margarita de Saboya en 1889."},{"id":"q2","question":"¿Qué forma de pasta toma su nombre del italiano por ''orejitas''?","options":[{"id":"a","text":"Farfalle","is_correct":false},{"id":"b","text":"Orecchiette","is_correct":true},{"id":"c","text":"Fusilli","is_correct":false},{"id":"d","text":"Rigatoni","is_correct":false}],"explanation":"Orecchiette significa ''orejitas'' en italiano; es una pasta emblemática de la región de Puglia."},{"id":"q3","question":"El risotto alla milanese, coloreado con azafrán, es un clásico de qué ciudad?","options":[{"id":"a","text":"Venecia","is_correct":false},{"id":"b","text":"Nápoles","is_correct":false},{"id":"c","text":"Milán","is_correct":true},{"id":"d","text":"Florencia","is_correct":false}],"explanation":"El risotto alla milanese lleva el nombre de Milán, en Lombardía; el azafrán le da su color dorado."},{"id":"q4","question":"¿Qué queso cremoso es imprescindible en un tiramisú clásico?","options":[{"id":"a","text":"Mascarpone","is_correct":true},{"id":"b","text":"Ricotta","is_correct":false},{"id":"c","text":"Gorgonzola","is_correct":false},{"id":"d","text":"Provolone","is_correct":false}],"explanation":"El tiramisú alterna bizcochos savoiardi mojados en café con una crema de mascarpone."},{"id":"q5","question":"¿Con qué carne curada se prepara la carbonara auténtica?","options":[{"id":"a","text":"Tocino ahumado","is_correct":false},{"id":"b","text":"Guanciale","is_correct":true},{"id":"c","text":"Salami","is_correct":false},{"id":"d","text":"Jamón cocido","is_correct":false}],"explanation":"El guanciale, papada de cerdo curada, es la carne tradicional de la carbonara romana, con huevo y pecorino."},{"id":"q6","question":"¿Con qué frutos secos se machaca la albahaca en el pesto alla genovese clásico?","options":[{"id":"a","text":"Nueces","is_correct":false},{"id":"b","text":"Almendras","is_correct":false},{"id":"c","text":"Piñones","is_correct":true},{"id":"d","text":"Avellanas","is_correct":false}],"explanation":"El pesto alla genovese combina albahaca, piñones, ajo, aceite de oliva y queso curado."},{"id":"q7","question":"¿En qué región se centra la zona protegida de producción del queso Parmigiano-Reggiano?","options":[{"id":"a","text":"Emilia-Romaña","is_correct":true},{"id":"b","text":"Sicilia","is_correct":false},{"id":"c","text":"Piamonte","is_correct":false},{"id":"d","text":"Cerdeña","is_correct":false}],"explanation":"Su zona protegida cubre Parma, Reggio Emilia, Módena y partes de las provincias de Bolonia y Mantua."},{"id":"q8","question":"¿Qué certifica el sello «DOP» en un alimento italiano?","options":[{"id":"a","text":"Que es ecológico","is_correct":false},{"id":"b","text":"Que se produce en una zona definida con métodos reconocidos","is_correct":true},{"id":"c","text":"Que no lleva aditivos","is_correct":false},{"id":"d","text":"Que solo se exporta dentro de la UE","is_correct":false}],"explanation":"DOP significa Denominazione di Origine Protetta, la denominación de origen protegida."}]'::jsonb,
  null,
  array['comida', 'trivia', 'italia', 'cocina italiana']::text[],
  3,
  'published',
  false,
  false,
  now()
)
on conflict (slug) do nothing;

insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'en-mexican-food-trivia',
  'Mexican Food Trivia: Corn, Chiles and Tequila',
  'Eight questions on the foundations of Mexican cuisine: nixtamalised corn, mole, tacos, chiles and tequila''s protected origin.',
  'trivia',
  'medium',
  'en',
  (select id from public.categories where slug = 'food-drink'),
  '[{"id":"q1","question":"Nixtamalisation, the process behind tortillas, is cooking corn in what?","options":[{"id":"a","text":"Vinegar","is_correct":false},{"id":"b","text":"An alkaline solution with slaked lime","is_correct":true},{"id":"c","text":"Sea water","is_correct":false},{"id":"d","text":"Milk","is_correct":false}],"explanation":"Nixtamalisation soaks corn in calcium hydroxide, which frees nutrients and lets the dough hold together."},{"id":"q2","question":"Mole poblano takes its name from which Mexican state?","options":[{"id":"a","text":"Oaxaca","is_correct":false},{"id":"b","text":"Jalisco","is_correct":false},{"id":"c","text":"Puebla","is_correct":true},{"id":"d","text":"Yucatán","is_correct":false}],"explanation":"Mole poblano is the emblematic sauce of Puebla, built on chiles, spices and a touch of chocolate."},{"id":"q3","question":"Tacos al pastor are cooked on a vertical spit, a technique brought by immigrants from which country?","options":[{"id":"a","text":"Lebanon","is_correct":true},{"id":"b","text":"Spain","is_correct":false},{"id":"c","text":"France","is_correct":false},{"id":"d","text":"China","is_correct":false}],"explanation":"Lebanese immigrants brought spit-roasting to Mexico; pork replaced lamb and the taco al pastor was born."},{"id":"q4","question":"Which chile is a ripe jalapeño that has been dried and smoked?","options":[{"id":"a","text":"Poblano","is_correct":false},{"id":"b","text":"Ancho","is_correct":false},{"id":"c","text":"Guajillo","is_correct":false},{"id":"d","text":"Chipotle","is_correct":true}],"explanation":"A chipotle is a smoke-dried ripe jalapeño; the ancho is instead the dried form of the poblano."},{"id":"q5","question":"In which year was tequila''s Denominación de Origen established in Mexico?","options":[{"id":"a","text":"1958","is_correct":false},{"id":"b","text":"1974","is_correct":true},{"id":"c","text":"1988","is_correct":false},{"id":"d","text":"2004","is_correct":false}],"explanation":"Mexico published the tequila denomination of origin in 1974, the first granted to a Mexican product."},{"id":"q6","question":"Tequila may be produced primarily in which Mexican state?","options":[{"id":"a","text":"Chihuahua","is_correct":false},{"id":"b","text":"Veracruz","is_correct":false},{"id":"c","text":"Chiapas","is_correct":false},{"id":"d","text":"Jalisco","is_correct":true}],"explanation":"The denomination of origin covers all of Jalisco and specific municipalities in four other states."},{"id":"q7","question":"Tequila is distilled from which plant?","options":[{"id":"a","text":"Sugar cane","is_correct":false},{"id":"b","text":"Blue agave","is_correct":true},{"id":"c","text":"Corn","is_correct":false},{"id":"d","text":"Nopal cactus","is_correct":false}],"explanation":"Tequila is made from Agave tequilana Weber, blue variety; the cooked hearts are fermented and distilled."},{"id":"q8","question":"Pozole, the festive Mexican soup, is built around which ingredient?","options":[{"id":"a","text":"Hominy corn","is_correct":true},{"id":"b","text":"Rice","is_correct":false},{"id":"c","text":"Lentils","is_correct":false},{"id":"d","text":"Black beans","is_correct":false}],"explanation":"Pozole is made with large nixtamalised corn kernels that bloom in the broth, served with meat and garnishes."}]'::jsonb,
  null,
  array['food', 'trivia', 'mexico', 'mexican cuisine']::text[],
  3,
  'published',
  false,
  false,
  now()
)
on conflict (slug) do nothing;

insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'es-trivia-comida-mexicana',
  'Trivia de comida mexicana: maíz, chiles y tequila',
  'Ocho preguntas sobre las bases de la cocina mexicana: maíz nixtamalizado, mole, tacos, chiles y la denominación del tequila.',
  'trivia',
  'medium',
  'es',
  (select id from public.categories where slug = 'food-drink'),
  '[{"id":"q1","question":"La nixtamalización, el proceso detrás de las tortillas, consiste en cocer el maíz en qué?","options":[{"id":"a","text":"Vinagre","is_correct":false},{"id":"b","text":"Una solución alcalina con cal","is_correct":true},{"id":"c","text":"Agua de mar","is_correct":false},{"id":"d","text":"Leche","is_correct":false}],"explanation":"La nixtamalización remoja el maíz en hidróxido de calcio, lo que libera nutrientes y permite formar la masa."},{"id":"q2","question":"¿De qué estado mexicano toma el nombre el mole poblano?","options":[{"id":"a","text":"Oaxaca","is_correct":false},{"id":"b","text":"Jalisco","is_correct":false},{"id":"c","text":"Puebla","is_correct":true},{"id":"d","text":"Yucatán","is_correct":false}],"explanation":"El mole poblano es la salsa emblemática de Puebla, hecha con chiles, especias y un toque de chocolate."},{"id":"q3","question":"Los tacos al pastor se cocinan en un asador vertical, técnica traída por inmigrantes de qué país?","options":[{"id":"a","text":"El Líbano","is_correct":true},{"id":"b","text":"España","is_correct":false},{"id":"c","text":"Francia","is_correct":false},{"id":"d","text":"China","is_correct":false}],"explanation":"Los inmigrantes libaneses llevaron el asado en trompo a México; el cerdo sustituyó al cordero y nació el taco al pastor."},{"id":"q4","question":"¿Qué chile es un jalapeño maduro que ha sido secado y ahumado?","options":[{"id":"a","text":"Poblano","is_correct":false},{"id":"b","text":"Ancho","is_correct":false},{"id":"c","text":"Guajillo","is_correct":false},{"id":"d","text":"Chipotle","is_correct":true}],"explanation":"El chipotle es un jalapeño maduro secado al humo; el ancho es en cambio la forma seca del chile poblano."},{"id":"q5","question":"¿En qué año se estableció en México la Denominación de Origen del tequila?","options":[{"id":"a","text":"1958","is_correct":false},{"id":"b","text":"1974","is_correct":true},{"id":"c","text":"1988","is_correct":false},{"id":"d","text":"2004","is_correct":false}],"explanation":"México publicó la denominación de origen del tequila en 1974, la primera otorgada a un producto mexicano."},{"id":"q6","question":"¿En qué estado mexicano puede producirse principalmente el tequila?","options":[{"id":"a","text":"Chihuahua","is_correct":false},{"id":"b","text":"Veracruz","is_correct":false},{"id":"c","text":"Chiapas","is_correct":false},{"id":"d","text":"Jalisco","is_correct":true}],"explanation":"La denominación de origen cubre todo Jalisco y municipios específicos de otros cuatro estados."},{"id":"q7","question":"¿De qué planta se destila el tequila?","options":[{"id":"a","text":"La caña de azúcar","is_correct":false},{"id":"b","text":"El agave azul","is_correct":true},{"id":"c","text":"El maíz","is_correct":false},{"id":"d","text":"El nopal","is_correct":false}],"explanation":"El tequila se hace con Agave tequilana Weber, variedad azul; sus piñas cocidas se fermentan y destilan."},{"id":"q8","question":"¿Alrededor de qué ingrediente se construye el pozole, la sopa festiva mexicana?","options":[{"id":"a","text":"El maíz nixtamalizado","is_correct":true},{"id":"b","text":"El arroz","is_correct":false},{"id":"c","text":"Las lentejas","is_correct":false},{"id":"d","text":"Los frijoles negros","is_correct":false}],"explanation":"El pozole se hace con granos grandes de maíz cacahuazintle que florecen en el caldo, con carne y guarniciones."}]'::jsonb,
  null,
  array['comida', 'trivia', 'méxico', 'cocina mexicana']::text[],
  3,
  'published',
  false,
  false,
  now()
)
on conflict (slug) do nothing;

insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'en-japanese-food-trivia',
  'Japanese Food Trivia: Sushi, Ramen and Beyond',
  'Eight questions on the staples of Japanese cuisine: sushi, ramen, tempura, sake and the UNESCO-listed washoku tradition.',
  'trivia',
  'medium',
  'en',
  (select id from public.categories where slug = 'food-drink'),
  '[{"id":"q1","question":"The word ''sushi'' actually refers to which part of the dish?","options":[{"id":"a","text":"The raw fish","is_correct":false},{"id":"b","text":"The vinegared rice","is_correct":true},{"id":"c","text":"The seaweed wrap","is_correct":false},{"id":"d","text":"The soy sauce","is_correct":false}],"explanation":"Sushi means vinegared rice; it can be served with many toppings, not only raw fish."},{"id":"q2","question":"Nigiri sushi was created in the early 19th century as street food in which city?","options":[{"id":"a","text":"Kyoto","is_correct":false},{"id":"b","text":"Osaka","is_correct":false},{"id":"c","text":"Edo, today''s Tokyo","is_correct":true},{"id":"d","text":"Nagasaki","is_correct":false}],"explanation":"Hanaya Yohei is credited with serving the first nigiri around the 1820s in Edo, the city that became Tokyo."},{"id":"q3","question":"Which broth of pork bones simmered for hours names a style of ramen?","options":[{"id":"a","text":"Tonkotsu","is_correct":true},{"id":"b","text":"Miso","is_correct":false},{"id":"c","text":"Shoyu","is_correct":false},{"id":"d","text":"Shio","is_correct":false}],"explanation":"Tonkotsu ramen uses a creamy pork-bone broth; miso, shoyu and shio describe seasoning bases instead."},{"id":"q4","question":"Tempura frying reached Japan in the 16th century through traders and missionaries from which country?","options":[{"id":"a","text":"China","is_correct":false},{"id":"b","text":"Portugal","is_correct":true},{"id":"c","text":"Spain","is_correct":false},{"id":"d","text":"The Netherlands","is_correct":false}],"explanation":"Portuguese traders and missionaries brought battered frying to Nagasaki in the 1500s."},{"id":"q5","question":"Sake is brewed by fermenting which grain?","options":[{"id":"a","text":"Barley","is_correct":false},{"id":"b","text":"Rice","is_correct":true},{"id":"c","text":"Wheat","is_correct":false},{"id":"d","text":"Buckwheat","is_correct":false}],"explanation":"Sake is brewed from polished rice in a process closer to beer-making than to wine-making."},{"id":"q6","question":"In which year did UNESCO inscribe washoku, traditional Japanese cuisine, as intangible cultural heritage?","options":[{"id":"a","text":"2008","is_correct":false},{"id":"b","text":"2010","is_correct":false},{"id":"c","text":"2013","is_correct":true},{"id":"d","text":"2016","is_correct":false}],"explanation":"Washoku joined the UNESCO Intangible Cultural Heritage list in December 2013."},{"id":"q7","question":"Which ''fifth taste'' did the chemist Kikunae Ikeda identify in 1908?","options":[{"id":"a","text":"Umami","is_correct":true},{"id":"b","text":"Kokumi","is_correct":false},{"id":"c","text":"Sourness","is_correct":false},{"id":"d","text":"Astringency","is_correct":false}],"explanation":"Ikeda isolated glutamate from kombu dashi and named its savoury taste ''umami''."},{"id":"q8","question":"Miso is a paste made mainly by fermenting what?","options":[{"id":"a","text":"Rice noodles","is_correct":false},{"id":"b","text":"Soybeans","is_correct":true},{"id":"c","text":"Seaweed","is_correct":false},{"id":"d","text":"Sesame seeds","is_correct":false}],"explanation":"Miso ferments soybeans with koji mould and salt; the main types are white, red and blended."}]'::jsonb,
  null,
  array['food', 'trivia', 'japan', 'japanese cuisine']::text[],
  3,
  'published',
  false,
  false,
  now()
)
on conflict (slug) do nothing;

insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'es-trivia-comida-japonesa',
  'Trivia de comida japonesa: sushi, ramen y más',
  'Ocho preguntas sobre los pilares de la cocina japonesa: sushi, ramen, tempura, sake y la tradición washoku de la UNESCO.',
  'trivia',
  'medium',
  'es',
  (select id from public.categories where slug = 'food-drink'),
  '[{"id":"q1","question":"La palabra «sushi» en realidad se refiere a qué parte del plato?","options":[{"id":"a","text":"Al pescado crudo","is_correct":false},{"id":"b","text":"Al arroz avinagrado","is_correct":true},{"id":"c","text":"Al alga que lo envuelve","is_correct":false},{"id":"d","text":"A la salsa de soya","is_correct":false}],"explanation":"Sushi significa arroz avinagrado; puede servirse con muchos acompañamientos, no solo pescado crudo."},{"id":"q2","question":"El nigiri sushi nació a comienzos del siglo XIX como comida callejera en qué ciudad?","options":[{"id":"a","text":"Kioto","is_correct":false},{"id":"b","text":"Osaka","is_correct":false},{"id":"c","text":"Edo, la actual Tokio","is_correct":true},{"id":"d","text":"Nagasaki","is_correct":false}],"explanation":"Se atribuye a Hanaya Yohei el primer nigiri, servido hacia la década de 1820 en Edo, la ciudad que se convirtió en Tokio."},{"id":"q3","question":"¿Qué caldo de huesos de cerdo cocido por horas da nombre a un estilo de ramen?","options":[{"id":"a","text":"Tonkotsu","is_correct":true},{"id":"b","text":"Miso","is_correct":false},{"id":"c","text":"Shoyu","is_correct":false},{"id":"d","text":"Shio","is_correct":false}],"explanation":"El ramen tonkotsu usa un caldo cremoso de huesos de cerdo; miso, shoyu y shio describen bases de sazón."},{"id":"q4","question":"La técnica de la tempura llegó a Japón en el siglo XVI por comerciantes y misioneros de qué país?","options":[{"id":"a","text":"China","is_correct":false},{"id":"b","text":"Portugal","is_correct":true},{"id":"c","text":"España","is_correct":false},{"id":"d","text":"Países Bajos","is_correct":false}],"explanation":"Los portugueses llevaron la fritura enharinada a Nagasaki en el siglo XVI."},{"id":"q5","question":"¿Con qué grano fermentado se elabora el sake?","options":[{"id":"a","text":"Cebada","is_correct":false},{"id":"b","text":"Arroz","is_correct":true},{"id":"c","text":"Trigo","is_correct":false},{"id":"d","text":"Trigo sarraceno","is_correct":false}],"explanation":"El sake se fermenta a partir de arroz pulido, en un proceso más parecido al de la cerveza que al del vino."},{"id":"q6","question":"¿En qué año inscribió la UNESCO el washoku, la cocina tradicional japonesa, como patrimonio inmaterial?","options":[{"id":"a","text":"2008","is_correct":false},{"id":"b","text":"2010","is_correct":false},{"id":"c","text":"2013","is_correct":true},{"id":"d","text":"2016","is_correct":false}],"explanation":"El washoku entró en la lista de Patrimonio Cultural Inmaterial de la UNESCO en diciembre de 2013."},{"id":"q7","question":"¿Qué ''quinto sabor'' identificó el químico Kikunae Ikeda en 1908?","options":[{"id":"a","text":"El umami","is_correct":true},{"id":"b","text":"El kokumi","is_correct":false},{"id":"c","text":"La acidez","is_correct":false},{"id":"d","text":"La astringencia","is_correct":false}],"explanation":"Ikeda aisló el glutamato del caldo de alga kombu y llamó umami a su sabor sabroso."},{"id":"q8","question":"¿Qué se fermenta principalmente para obtener la pasta de miso?","options":[{"id":"a","text":"Fideos de arroz","is_correct":false},{"id":"b","text":"Soya","is_correct":true},{"id":"c","text":"Algas","is_correct":false},{"id":"d","text":"Semillas de sésamo","is_correct":false}],"explanation":"El miso fermenta soya con el hongo koji y sal; sus tipos principales son blanco, rojo y mezclado."}]'::jsonb,
  null,
  array['comida', 'trivia', 'japón', 'cocina japonesa']::text[],
  3,
  'published',
  false,
  false,
