insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'en-spanish-food-trivia',
  'Spanish Food Trivia: Paella, Tapas and More',
  'Eight questions on the dishes of Spain: paella and its socarrat, tapas, jamón ibérico, tortilla and churros.',
  'trivia',
  'easy',
  'en',
  (select id from public.categories where slug = 'food-drink'),
  '[{"id":"q1","question":"In a good paella, what is the crispy layer of toasted rice at the bottom called?","options":[{"id":"a","text":"The socarrat","is_correct":true},{"id":"b","text":"The alioli","is_correct":false},{"id":"c","text":"The sofrito","is_correct":false},{"id":"d","text":"The pimentón","is_correct":false}],"explanation":"Valencians prize the socarrat, the golden crust that forms when the broth finishes cooking."},{"id":"q2","question":"The word ''tapa'' literally means what in Spanish?","options":[{"id":"a","text":"Small plate","is_correct":false},{"id":"b","text":"Lid or cover","is_correct":true},{"id":"c","text":"Bite","is_correct":false},{"id":"d","text":"Toast","is_correct":false}],"explanation":"Tapa comes from tapar, ''to cover'': tradition says slices of ham or bread once covered drinks."},{"id":"q3","question":"Jamón ibérico de bellota comes from pigs that fed mainly on what?","options":[{"id":"a","text":"Corn","is_correct":false},{"id":"b","text":"Olives","is_correct":false},{"id":"c","text":"Acorns","is_correct":true},{"id":"d","text":"Chestnuts","is_correct":false}],"explanation":"During the montanera season the pigs roam oak pastures and eat acorns, which give the ham its flavour."},{"id":"q4","question":"Spanish tortilla de patatas is made mainly with eggs and which other ingredient?","options":[{"id":"a","text":"Potatoes","is_correct":true},{"id":"b","text":"Rice","is_correct":false},{"id":"c","text":"Chickpeas","is_correct":false},{"id":"d","text":"Bread","is_correct":false}],"explanation":"The tortilla española combines eggs with potatoes cooked slowly in olive oil; onion stays optional and debated."},{"id":"q5","question":"In Spain, churros for breakfast are traditionally dipped in what?","options":[{"id":"a","text":"Café con leche","is_correct":false},{"id":"b","text":"Thick hot chocolate","is_correct":true},{"id":"c","text":"Warm milk","is_correct":false},{"id":"d","text":"Honey","is_correct":false}],"explanation":"Churros con chocolate pair the fried dough with a cup of hot chocolate thick enough to coat it."},{"id":"q6","question":"Which southern region produces most of Spain''s olive oil?","options":[{"id":"a","text":"Galicia","is_correct":false},{"id":"b","text":"Catalonia","is_correct":false},{"id":"c","text":"Andalusia","is_correct":true},{"id":"d","text":"The Basque Country","is_correct":false}],"explanation":"Andalusia grows most of Spain''s olive oil; the province of Jaén alone has tens of millions of olive trees."},{"id":"q7","question":"Which small green peppers are fried and salted, and famously ''some are hot, some are not''?","options":[{"id":"a","text":"Padrón peppers","is_correct":true},{"id":"b","text":"Jalapeños","is_correct":false},{"id":"c","text":"Piquillo peppers","is_correct":false},{"id":"d","text":"Habaneros","is_correct":false}],"explanation":"Pimientos de Padrón, from Galicia, are mostly mild, but the occasional one bites back."},{"id":"q8","question":"Manchego cheese is made from the milk of which animal?","options":[{"id":"a","text":"Cow","is_correct":false},{"id":"b","text":"Goat","is_correct":false},{"id":"c","text":"Sheep","is_correct":true},{"id":"d","text":"Buffalo","is_correct":false}],"explanation":"Manchego carries a protected designation of origin and is made only with milk from Manchega sheep."}]'::jsonb,
  null,
  array['food', 'trivia', 'spain', 'spanish cuisine']::text[],
  3,
  'published',
  false,
  false,
  now()
)
on conflict (slug) do nothing;

insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
