values (
  'es-trivia-comida-espanola',
  'Trivia de comida española: paella, tapas y más',
  'Ocho preguntas sobre la cocina de España: la paella y su socarrat, las tapas, el jamón ibérico, la tortilla y los churros.',
  'trivia',
  'easy',
  'es',
  (select id from public.categories where slug = 'food-drink'),
  '[{"id":"q1","question":"En una buena paella, ¿cómo se llama la capa tostada y crujiente de arroz del fondo?","options":[{"id":"a","text":"El socarrat","is_correct":true},{"id":"b","text":"El alioli","is_correct":false},{"id":"c","text":"El sofrito","is_correct":false},{"id":"d","text":"El pimentón","is_correct":false}],"explanation":"Los valencianos aprecian el socarrat, la costra dorada que se forma cuando el caldo termina de cocerse."},{"id":"q2","question":"¿Qué significa literalmente la palabra «tapa»?","options":[{"id":"a","text":"Un plato pequeño","is_correct":false},{"id":"b","text":"Una cubierta","is_correct":true},{"id":"c","text":"Un bocado","is_correct":false},{"id":"d","text":"Un brindis","is_correct":false}],"explanation":"Tapa viene de tapar: la tradición dice que lonchas de jamón o pan cubrían antes las copas."},{"id":"q3","question":"¿De qué se alimentan principalmente los cerdos del jamón ibérico de bellota?","options":[{"id":"a","text":"Maíz","is_correct":false},{"id":"b","text":"Aceitunas","is_correct":false},{"id":"c","text":"Bellotas","is_correct":true},{"id":"d","text":"Castañas","is_correct":false}],"explanation":"En la montanera los cerdos pastan en la dehesa y comen bellotas, que dan al jamón su sabor."},{"id":"q4","question":"¿Con qué otro ingrediente se hace principalmente la tortilla de patatas?","options":[{"id":"a","text":"Papas","is_correct":true},{"id":"b","text":"Arroz","is_correct":false},{"id":"c","text":"Garbanzos","is_correct":false},{"id":"d","text":"Pan","is_correct":false}],"explanation":"La tortilla española combina huevos con papas cocidas a fuego lento en aceite de oliva; la cebolla es opcional y debatida."},{"id":"q5","question":"¿En qué se mojan tradicionalmente los churros del desayuno en España?","options":[{"id":"a","text":"Café con leche","is_correct":false},{"id":"b","text":"Chocolate caliente espeso","is_correct":true},{"id":"c","text":"Leche tibia","is_correct":false},{"id":"d","text":"Miel","is_correct":false}],"explanation":"Los churros con chocolate combinan la masa frita con una taza de chocolate tan espeso que la cubre."},{"id":"q6","question":"¿Qué región del sur produce la mayor parte del aceite de oliva de España?","options":[{"id":"a","text":"Galicia","is_correct":false},{"id":"b","text":"Cataluña","is_correct":false},{"id":"c","text":"Andalucía","is_correct":true},{"id":"d","text":"El País Vasco","is_correct":false}],"explanation":"Andalucía produce la mayor parte del aceite español; solo la provincia de Jaén tiene decenas de millones de olivos."},{"id":"q7","question":"¿Qué pimientos verdes pequeños se fríen con sal y se dice que ''unos pican y otros no''?","options":[{"id":"a","text":"Los pimientos de Padrón","is_correct":true},{"id":"b","text":"Los jalapeños","is_correct":false},{"id":"c","text":"Los pimientos del piquillo","is_correct":false},{"id":"d","text":"Los habaneros","is_correct":false}],"explanation":"Los pimientos de Padrón, de Galicia, casi no pican, salvo alguno que sorprende."},{"id":"q8","question":"¿De la leche de qué animal se hace el queso manchego?","options":[{"id":"a","text":"Vaca","is_correct":false},{"id":"b","text":"Cabra","is_correct":false},{"id":"c","text":"Oveja","is_correct":true},{"id":"d","text":"Búfala","is_correct":false}],"explanation":"El manchego tiene denominación de origen protegida y solo se hace con leche de oveja manchega."}]'::jsonb,
  null,
  array['comida', 'trivia', 'españa', 'cocina española']::text[],
  3,
  'published',
  false,
  false,
  now()
)
on conflict (slug) do nothing;

